using System.Linq;
using UnityEngine;
namespace IanGame {
// One shared table. The sprite mask contains exactly the actors who really occupy
// their reserved chairs; it never invents a parent or teleports a navigation actor.
[DefaultExecutionOrder(2000)]public sealed class FamilySharedDiningPresentation:MonoBehaviour {
 public LifeWorldController world;public WorldActivitySlot mother,father,player;public SpriteRenderer visual;public Sprite[] frames;
 public int Mask{get;private set;}public int Frame{get;private set;}public int[] ActorFrames{get;}=new int[3];SpriteRenderer[] slices;Sprite[][] cropped;WorldInteractable mom,dad;bool wasMom,wasDad;
 void Start(){slices=new SpriteRenderer[3];cropped=new Sprite[3][];for(int i=0;i<3;i++){var go=new GameObject("Shared tabletop animation region "+i,typeof(SpriteRenderer));go.transform.SetParent(visual.transform,false);slices[i]=go.GetComponent<SpriteRenderer>();slices[i].sharedMaterial=visual.sharedMaterial;cropped[i]=new Sprite[4];for(int f=0;f<4;f++){var source=frames[(1<<i)*4+f];var rect=source.rect;float width=rect.width/3;cropped[i][f]=Sprite.Create(source.texture,new Rect(rect.x+i*width,rect.y+14,width,rect.height-14),new Vector2(.5f,0),source.pixelsPerUnit);cropped[i][f].name="Family seated "+i+" frame "+f;}go.transform.localPosition=new Vector3((i-1)*frames[0].bounds.size.x/3,14/frames[0].pixelsPerUnit,0);slices[i].enabled=false;}mom=world.objects.FirstOrDefault(o=>o.npcId=="family-mother");dad=world.objects.FirstOrDefault(o=>o.npcId=="family-father");}
 bool Present(WorldActivitySlot seat,WorldInteractable actor){if(actor==null)return false;var animation=actor.GetComponent<WorldActorAnimation>();return seat.IsOccupied&&seat.Occupant==actor.npcId&&FamilyLife.IsFamilyRoom(actor.zone)&&Vector2.Distance(actor.transform.position,seat.Point)<.05f&&animation.Motion!=ActorMotion.Walk&&animation.Motion!=ActorMotion.SitDown&&animation.Motion!=ActorMotion.StandUp;}
 void LateUpdate(){if(mom==null)mom=world.objects.FirstOrDefault(o=>o.npcId=="family-mother");if(dad==null)dad=world.objects.FirstOrDefault(o=>o.npcId=="family-father");if(world.Service==null||frames==null||frames.Length<32)return;bool local=FamilyLife.IsFamilyRoom(world.CurrentZone?.id);bool m=local&&Present(mother,mom),d=local&&Present(father,dad),p=local&&player.IsOccupied&&player.Occupant=="player"&&Vector2.Distance(world.Player.Position,player.Point)<.05f&&world.Player.advanced.Motion==ActorMotion.Eat;
  Mask=(m?1:0)|(d?2:0)|(p?4:0);Frame=Mathf.FloorToInt(Time.unscaledTime*3)%4;visual.sprite=frames[0];visual.enabled=true;for(int i=0;i<3;i++){ActorFrames[i]=Mathf.FloorToInt(Time.unscaledTime*3+i*1.37f)%4;slices[i].sprite=cropped[i][ActorFrames[i]];slices[i].sortingOrder=visual.sortingOrder+2;slices[i].enabled=(Mask&(1<<i))!=0;}if(m){mom.visual.enabled=false;if(mom.shadow!=null)mom.shadow.enabled=false;}else if(wasMom&&mom!=null){mom.visual.enabled=local&&FamilyLife.IsFamilyRoom(mom.zone)&&!world.GetComponentsInChildren<WorldFacilityActivityPresentation>().Any(v=>v.IsPresenting&&v.slot.Occupant==mom.npcId);if(mom.shadow!=null)mom.shadow.enabled=mom.visual.enabled;}if(d){dad.visual.enabled=false;if(dad.shadow!=null)dad.shadow.enabled=false;}else if(wasDad&&dad!=null){dad.visual.enabled=local&&FamilyLife.IsFamilyRoom(dad.zone)&&!world.GetComponentsInChildren<WorldFacilityActivityPresentation>().Any(v=>v.IsPresenting&&v.slot.Occupant==dad.npcId);if(dad.shadow!=null)dad.shadow.enabled=dad.visual.enabled;}wasMom=m;wasDad=d;if(p){world.Player.sprite.enabled=false;if(world.Player.contactShadow!=null)world.Player.contactShadow.enabled=false;}
 }
 void OnDestroy(){if(cropped!=null)foreach(var row in cropped)foreach(var sprite in row)if(sprite!=null)Destroy(sprite);}
 void OnDisable(){if(world==null)return;foreach(var a in new[]{mom,dad})if(a!=null){bool local=world.CurrentZone!=null&&a.zone==world.CurrentZone.id;a.visual.enabled=local;if(a.shadow!=null)a.shadow.enabled=local;}}
}
}
